<?php
namespace App\Controllers\Admin;use App\Core\Controller;use App\Helpers\AdminAuth;
class Auth extends Controller {public function login():void{$this->handleCors();if(!$this->isPost())$this->error('Method not allowed',405);AdminAuth::ensure($this->db());$b=$this->getBody();$email=strtolower(trim((string)($b['email']??'')));$password=(string)($b['password']??'');$u=$this->db()->query('SELECT * FROM vp_admin_users WHERE email=? AND is_active=1 LIMIT 1',[$email])->row_array();if(!$u||!password_verify($password,$u['password_hash']))$this->error('Invalid credentials',401);AdminAuth::login($u);$this->success(AdminAuth::user(),'Login berhasil');}public function me():void{$this->handleCors();$u=AdminAuth::user();if(!$u)$this->error('Unauthorized',401);$this->success($u,'Authenticated');}public function logout():void{$this->handleCors();AdminAuth::logout();$this->success(null,'Logout berhasil');}}
